import{_ as d,a0 as u,w as o,s as l,ao as r,I as e,a1 as p,A as n,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在Ubuntu上安裝和配置Nvidia Optimus驅動 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu上安裝和配置Nvidia Optimus驅動 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu上安裝和配置Nvidia Optimus驅動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu上安裝和配置Nvidia Optimus驅動 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140804 How to install and configure Nvidia Optimus driver on Ubuntu","title":"在Ubuntu上安裝和配置Nvidia Optimus驅動","tag":"201410","desc":""},"relativePath":"201410/20140804 How to install and configure Nvidia Optimus driver on Ubuntu.md","filePath":"[post].md"}'),s={name:"201410/20140804 How to install and configure Nvidia Optimus driver on Ubuntu.md"};function m(v,i,b,f,g,N){const a=u("Link");return o(),l("div",null,[i[17]||(i[17]=r('<h1 id="在ubuntu上安裝和配置nvidia-optimus驅動" tabindex="-1">在Ubuntu上安裝和配置Nvidia Optimus驅動 <a class="header-anchor" href="#在ubuntu上安裝和配置nvidia-optimus驅動" aria-label="Permalink to “在Ubuntu上安裝和配置Nvidia Optimus驅動”">​</a></h1><p>Nvidia Optimus是一款利用“雙顯卡切換”技術的混合GPU系統，但長期以來受限於Linux系統上的諸多不便與限制。在數年的等待之後，搭載這全新內核的Ubuntu 14.04最終實現了非常容易安裝的專用驅動的兼容性。這篇文章首先為不熟悉Nvidia Optimus的讀者簡介相關背景，然後展示整個安裝過程。對於對Xorg有着豐富配置經驗的老手，可以直接跳到安裝部分。</p><h3 id="背景知識" tabindex="-1">背景知識 <a class="header-anchor" href="#背景知識" aria-label="Permalink to “背景知識”">​</a></h3><p>對那些不熟悉Nvidia Optimus的讀者，在板載Intel圖形芯片組和使用被稱為“GPU切換”、對需求有着更強大處理能力的NVIDA顯卡這兩者之間的進行切換是很有必要的。這麼做的主要目的是延長筆記本電池的使用壽命，以便在不需要Nvidia GPU的時候將其關閉。帶來的好處是顯而易見的，比如説你只是想簡單地打打字，筆記本電池可以撐8個小時；如果看高清視頻，可能就只能撐3個小時了。使用Windows時經常如此。</p><p><img src="https://farm6.staticflickr.com/5581/14612159387_2e89a52085_z.jpg" alt=""></p><p>幾年前，我買了一台上網本(Asus VX6)，犯的最蠢的一個錯誤就是沒有檢查Linux驅動兼容性。因為在以前，特別是對於一台上網本大小的設備，這根本不會是問題。即便某些驅動不是現成可用的，我也可以找到其它的辦法讓它正常工作，比如安裝專門模組或者使用反向移植。對我來説這是第一次——我的電腦預先配備了Nvidia ION2圖形顯卡。</p><p>在那時候，Nvidia的Optimus混合GPU硬件還是相當新的產品，而我也沒有預見到在這台機器上運行Linux會遇到什麼限制。如果你讀到了這裏，恰好對Linux系統有經驗，而且也在幾年前買過一台筆記本，你可能對這種痛苦感同身受。</p><p>[Bumblebee][4]項目直到最近因為得到Linux系統對混合圖形方面的支持才變得好起來。事實上，如果配置正確的話，通過命令列接口（如“optirun vlc”）讓你選定的應用程序能利用Nvidia顯卡功能是可行的，但讓HDMI一類的功能運轉起來就很不同了。(譯者注：Bumblebee 項目是把Nvidia的Optimus技術移到Linux上來。)</p><p>我之所以使用“如果配置正確的話”這個短語，是因為實際上為了讓它發揮出性能來往往不只是通過幾次嘗試去改變Xorg的配置就能做到的。如果你以前沒有使用過ppa-purge或者運行過“dpkg-reconfigure -phigh xserver-xorg”這類命令，那麼我可以向你保證修補Bumblebee的過程會讓你受益匪淺。</p>',9)),e("p",null,[p(a,{href:"http://xkcd.com/963"},{default:n(()=>[...i[0]||(i[0]=[e("img",{src:"https://farm6.staticflickr.com/5588/14798680495_947c38b043_o.png",alt:""},null,-1)])]),_:1})]),i[18]||(i[18]=r(`<p>在等待了很長一段時間後，Nvidia才發佈了支持Optimus的Linux驅動，但我們仍然沒有得到對雙顯卡切換的真正支持。然而，現在有了Ubuntu 14.04、nvidia-prime和nvidia-331驅動，任何人都可以在Intel芯片和Nvidia顯卡之間輕鬆切換。不過不幸的是，為了使切換生效，還是會受限於需要重啓X11視窗系統（通過註銷登錄實現）。</p><p>為了減輕這種不便，有一個小型程序用於快速切換，稍後我會給出。這個驅動程序的安裝就此成為一件輕而易舉的事了，HDMI也可以正常工作，這足以讓我心滿意足了。</p><h3 id="安裝nvidia-optimus驅動" tabindex="-1">安裝Nvidia Optimus驅動 <a class="header-anchor" href="#安裝nvidia-optimus驅動" aria-label="Permalink to “安裝Nvidia Optimus驅動”">​</a></h3><p>為了更快地描述這個過程，我假設你已經安裝好Ubuntu 14.04或者Mint 17。</p><p>作為一名系統管理員，最近我發現90%的Linux操作通過命令列執行起來更快，但這次我推薦使用“Additional Drivers”這個應用程序，你可能使用它安裝過網卡或聲卡驅動。</p><p><img src="https://farm4.staticflickr.com/3886/14795564221_753f9e2d99_z.jpg" alt=""></p><p><strong>注意：下面的所有命令都是在~#提示符下執行的，需要root權限執行。在運行命令前，要麼使用“sudo su”（切換到root權限），要麼在每條命令的開頭使用sudo運行。</strong></p><p>你也可以在命令列輸入如下命令進行安裝：</p><pre><code> ~# apt-get install nvidia-331 nvidia-settings nvidia-prime 
</code></pre><p>接下來是重啓。確保你沒有安裝類似於Bumblebee或其他已加載的Nvidia驅動，否則很可能會破壞你的X11。萬一你沒有進行全新安裝，之前有安裝過Bumblebee程序，那麼在安裝nvidia-331和nvidia-prime前運行下列命令：</p><pre><code> ~# apt-get purge libvdpau-va-gl1 bumblebee* nvidia*
</code></pre><h3 id="在nvidia和非nvidia顯卡之間切換" tabindex="-1">在Nvidia和非Nvidia顯卡之間切換 <a class="header-anchor" href="#在nvidia和非nvidia顯卡之間切換" aria-label="Permalink to “在Nvidia和非Nvidia顯卡之間切換”">​</a></h3><p>你可以通過按下Alt+F2或者從命令列鍵入下列命令實現Nvidia和非Nvidia（如Intel）顯卡之間的切換：</p><pre><code>~$ nvidia-settings 
</code></pre><p><strong>注意：~$表示不以root用户身份執行。</strong></p><p><img src="https://farm4.staticflickr.com/3921/14796320814_de5c9882c2_z.jpg" alt=""></p><p>你也可以使用命令列設置默認使用哪一塊顯卡：</p><pre><code>~# prime-select intel (或 nvidia)
</code></pre><p>使用這個命令進行切換：</p><pre><code>~# prime-switch intel (或 nvidia)
</code></pre><p>兩個命令的生效都需要重啓X11，可以通過註銷和重新登錄實現。當然重啓電腦也行。</p><p>對Ubuntu用户鍵入命令：</p><pre><code>~# service lightdm restart
</code></pre><p>對Mint用户鍵入命令：</p><pre><code>~# service mdm restart
</code></pre><p>鍵入這個命令確認哪一塊顯卡在運行：</p><pre><code>~# prime-select query
</code></pre><p>最後，你可以通過添加ppa:nilarimogard/webupd8來安裝叫做prime-indicator的程序包，實現通過工具欄快速切換來重啓Xserver會話。要安裝它，只需要運行：</p><pre><code>~# add-apt-repository ppa:nilarimogard/webupd8
~# apt-get update
~# apt-get install mesa-utils prime-indicator 
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>總而言之，這個方法仍不完美，但至少它能簡單易用地提供合適的專門驅動支持。很多人不會使用這個安裝方法來設置Bumblebee，因為他們發現使用Nvidia驅動會很快耗完電池。對我個人的使用來説，這是一個更好的方法，因為我使用Nvidia只為了滿足HDMI輸出，這表示我必須把電腦插上電源才行。不然的話，Intel的顯卡對我的筆記本來説夠用了，因為除了頻繁地使用Libreoffice、Chromium和Terminator這幾個軟件我別無所求。</p><p>如果你寧願選擇在默認情況下使用Intel顯卡，為運行特定的應用程序使用Nvidia顯卡，你應該去閲讀那些Bumblebee教程。一旦你得以讓Bumblebee正常工作起來，我建議你記錄下用來配置電腦的命令和過程。因為沒有什麼比9個月之後再來一次全新安裝但忘記了上次是如何成功安裝更糟糕的事情了。</p>`,32)),e("p",null,[i[2]||(i[2]=t("也可以花時間查看一下這個我偶然發現的",-1)),p(a,{href:"https://devtalk.nvidia.com/default/topic/705993/easy-switch-between-bumblebee-and-nvidia-prime/"},{default:n(()=>[...i[1]||(i[1]=[t("腳本",-1)])]),_:1}),i[3]||(i[3]=t("，用來方便地在Bumblebee和Nvidia-Prime之間進行切換，但我必須強調並沒有親自對此進行實驗。",-1))]),i[19]||(i[19]=e("p",null,"最後，我感到非常慚愧，寫了這麼多才得以為Linux上的顯卡提供了專門支持，但仍然不能實現雙顯卡切換，因為混合圖形技術似乎是便攜式設備的未來。一般情況下，AMD會發布Linux平台上的驅動支持，但我認為Optimus是目前為止我遇到過的最糟糕的硬件支持問題。",-1)),i[20]||(i[20]=e("p",null,"不管這篇教程對你的使用是否完美，但這確實是利用這塊Nvidia顯卡最容易的方法。你可以試着在Intel顯卡上只運行最新的Unity，然後考慮2到3個小時的電池壽命是否值得權衡。",-1)),i[21]||(i[21]=e("hr",null,null,-1)),e("p",null,[i[5]||(i[5]=t("via: ",-1)),p(a,{href:"http://xmodulo.com/2014/08/install-configure-nvidia-optimus-driver-ubuntu.html"},{default:n(()=>[...i[4]||(i[4]=[t("http://xmodulo.com/2014/08/install-configure-nvidia-optimus-driver-ubuntu.html",-1)])]),_:1})]),e("p",null,[i[9]||(i[9]=t("作者：",-1)),p(a,{href:"http://xmodulo.com/author/christopher"},{default:n(()=>[...i[6]||(i[6]=[t("Christopher Ward",-1)])]),_:1}),i[10]||(i[10]=t(" 譯者：",-1)),p(a,{href:"https://github.com/KayGuoWhu"},{default:n(()=>[...i[7]||(i[7]=[t("KayGuoWhu",-1)])]),_:1}),i[11]||(i[11]=t(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:n(()=>[...i[8]||(i[8]=[t("wxy",-1)])]),_:1})]),e("p",null,[i[14]||(i[14]=t("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[12]||(i[12]=[t("LCTT",-1)])]),_:1}),i[15]||(i[15]=t(" 原創翻譯，",-1)),p(a,{href:"http://linux.cn/"},{default:n(()=>[...i[13]||(i[13]=[t("Linux中國",-1)])]),_:1}),i[16]||(i[16]=t(" 榮譽推出",-1))])])}const O=d(s,[["render",m]]);export{h as __pageData,O as default};
